package org.apache.commons.math3.complex;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Math_5_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        Complex zeroComplex = new Complex(0.0, 0.0);
        Complex result = zeroComplex.reciprocal();

        // The expected behavior after the fix is to return Complex.INF
        // But in the pre-fix version, it incorrectly returns Complex.NaN
        assertFalse("Expected result to be Complex.INF", result.isNaN());
    }
}

